def create_from_rows(  # noqa: D102
    column_names: Sequence[str], rows: Iterable[Sequence[InputCellValue]]
) -> MetricFlowDataTable:
    builder = _MetricFlowDataTableBuilder(column_names)
    for row in rows:
        builder.add_row(row)
    return builder.build()
